import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header for empty invoices', () => {
  const r = exportCsv([]);
  assert.equal(r, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv returns header for null invoices', () => {
  const r = exportCsv(null);
  assert.equal(r, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv exports single issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  assert.equal(lines.length, 3); // header + 1 invoice + empty (from trailing \n)
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.match(lines[1], /^INV-2026-0001/);
});

test('exportCsv exports draft invoice with DRAFT as number', () => {
  const draft = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });

  const r = exportCsv([draft.value]);
  const lines = r.split('\n');
  assert.match(lines[1], /^DRAFT,/);
});

test('exportCsv includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // C-003 is "Studio Moderne" according to customers.json
  assert.equal(fields[1], 'Studio Moderne');
});

test('exportCsv formats amounts as euros with 2 decimals', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // subtotal = 8500 cents = 85.00
  assert.equal(fields[5], '85.00');
  // vat = 1785 cents = 17.85
  assert.equal(fields[7], '17.85');
  // total = 10285 cents = 102.85
  assert.equal(fields[8], '102.85');
});

test('exportCsv escapes customer name with comma', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  // C-001 is "Acme, Inc." which has a comma
  assert.match(lines[1], /"Acme, Inc\."/);
});

test('exportCsv escapes customer name with double quote', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  // C-002 is "Bob's \"Gallery\"" which has quotes
  assert.match(lines[1], /"Bob's ""Gallery"""/);
});

test('exportCsv exports multiple invoices', () => {
  const invoice1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const r = exportCsv([issued1.value, issued2.value]);
  const lines = r.split('\n');
  assert.equal(lines.length, 4); // header + 2 invoices + empty
  assert.match(lines[1], /^INV-2026-0001/);
  assert.match(lines[2], /^INV-2026-0002/);
});

test('exportCsv includes discount in export', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // subtotal = 8500, discount = 850
  assert.equal(fields[5], '85.00');
  assert.equal(fields[6], '8.50');
});

test('exportCsv includes VAT in export', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // vat = 1785 = 17.85
  assert.equal(fields[7], '17.85');
});

test('exportCsv includes correct due amount for unpaid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // total = 10285 = 102.85, due = 102.85 (unpaid)
  assert.equal(fields[9], '102.85');
});

test('exportCsv includes correct due amount for partially paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const partial = recordPayment(issued.value, { amount: 5000, date: '2026-10-10' });

  const r = exportCsv([partial.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // total = 51425 = 514.25, paid = 5000 = 50.00, due = 46425 = 464.25
  assert.equal(fields[9], '464.25');
});

test('exportCsv includes correct due amount for paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const paid = recordPayment(issued.value, { amount: 10285, date: '2026-10-10' });

  const r = exportCsv([paid.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // due = 0.00 (fully paid)
  assert.equal(fields[9], '0.00');
});

test('exportCsv ends with newline', () => {
  const r = exportCsv([]);
  assert.equal(r.slice(-1), '\n');

  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r2 = exportCsv([issued.value]);
  assert.equal(r2.slice(-1), '\n');
});

test('exportCsv has correct column order', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  const header = lines[0];
  assert.equal(
    header,
    'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'
  );
});

test('exportCsv includes status field', () => {
  const draft = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });

  const r = exportCsv([draft.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[4], 'draft');
});

test('exportCsv includes dueDate', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  const fields = lines[1].split(',');
  // NET14 from 2026-10-07 = 2026-10-21
  assert.equal(fields[3], '2026-10-21');
});

test('exportCsv preserves invoice order', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const invoice3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued3 = issueInvoice(invoice3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const r = exportCsv([issued1.value, issued2.value, issued3.value]);
  const lines = r.split('\n');
  assert.match(lines[1], /^INV-2026-0001,Acme, Inc\./);
  assert.match(lines[2], /^INV-2026-0002,Studio Moderne/);
  assert.match(lines[3], /^INV-2026-0003,Bob's ""Gallery""/);
});

test('exportCsv no thousands separator in amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }], // 120000 + VAT
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  const lines = r.split('\n');
  // 120000 cents = 1200.00 (not 1,200.00)
  assert.match(lines[1], /1200\.00/);
  assert.notMatch(lines[1], /1,200/);
});

test('exportCsv no currency sign in amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  const issued = issueInvoice(invoice.value, []);

  const r = exportCsv([issued.value]);
  assert.notMatch(r, /€/);
  assert.notMatch(r, /\$/);
});

